48	import java.io.IOException;
49	import java.io.UncheckedIOException;
50	import java.nio.charset.StandardCharsets;
51	import java.nio.file.Files;
52	import java.nio.file.Path;
53	import java.nio.file.StandardOpenOption;
54	import org.springframework.beans.factory.annotation.Value;
55	import org.springframework.stereotype.Service;
56	
57	/**
58	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
59	 * so tests can assert side-effects by reading that file — the second test-assertion channel
60	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
61	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
62	 *
63	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
64	 * SYNC) so a test reads the record immediately.
65	 */
66	@Service
67	public class Audit {
68	
69	    private final Path file;
70	
71	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
72	        this.file = Path.of(path);
73	    }
74	
75	    /** Append one audit record. Tests assert the exact line(s) in the file. */
76	    public synchronized void record(String entry) {
77	        try {
78	            Path parent = file.toAbsolutePath().getParent();
79	            if (parent != null) {
80	                Files.createDirectories(parent);
81	            }
82	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
83	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
84	        } catch (IOException e) {
85	            throw new UncheckedIOException(e);
86	        }
87	    }
88	
89	    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
90	    public synchronized void clear() {
91	        try {
92	            Files.deleteIfExists(file);
93	        } catch (IOException e) {
94	            throw new UncheckedIOException(e);
95	        }
96	    }
97	}
