123	                    @Override
124	                    protected Resource getResource(String resourcePath, Resource location) throws IOException {
125	                        if (resourcePath.startsWith("api/")) {
126	                            return null; // let the API handle / 404 it
127	                        }
128	                        Resource requested = location.createRelative(resourcePath);
129	                        return (requested.exists() && requested.isReadable())
130	                                ? requested
131	                                : location.createRelative("index.html");
132	                    }
