155	/**
156	 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
157	 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
158	 * ARRANGE data; they ASSERT only through the UI.
159	 */
160	@Profile("e2e")
161	@RestController
162	@RequestMapping("/__test__")
163	public class TestSupportController {
164	
165	    private static final Set<String> PERSON_FIELDS = Set.of("id", "name", "alpha", "beta", "gamma");
166	
167	    private static final Set<String> PATRON_FIELDS = Set.of("personId", "patronId");
168	
169	    private static final Set<String> SHEET_FIELDS = Set.of("id", "people", "patrons");
170	
171	    private final Audit audit;
172	    private final JdbcTemplate jdbc;
173	
174	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
175	        this.audit = audit;
176	        this.jdbc = jdbc;
177	    }
178	
179	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
180	    @PostMapping("/reset")
181	    @Transactional
182	    public void reset() {
183	        audit.clear();
184	        // Person is referenced by its patrons, so delete rather than truncate.
185	        jdbc.update("DELETE FROM person_patron");
186	        jdbc.update("DELETE FROM person");
187	        jdbc.update("DELETE FROM sheet");
188	        jdbc.execute("ALTER TABLE person ALTER COLUMN id RESTART WITH 1");
189	    }
190	
191	    /**
192	     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
193	     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
194	     */
195	    @PostMapping("/seed")
196	    @Transactional
197	    public void seed(@RequestBody Map<String, Object> fixture) {
198	        for (String key : fixture.keySet()) {
199	            if (!key.equals("people") && !key.equals("patrons") && !key.equals("sheets")) {
200	                throw badRequest("unknown fixture key: " + key);
201	            }
202	        }
203	        // People and patrons at the top level are on the unnamed sheet.
204	        seedSheet(null, fixture.get("people"), fixture.get("patrons"), "");
205	        for (Map<String, Object> sheet : rows(fixture.get("sheets"), "sheets")) {
206	            for (String field : sheet.keySet()) {
207	                if (!SHEET_FIELDS.contains(field)) {
208	                    throw badRequest("cannot store sheets." + field);
209	                }
210	            }
211	            if (!(sheet.get("id") instanceof String id) || id.isBlank()) {
212	                throw badRequest("sheets.id is required");
213	            }
214	            jdbc.update("INSERT INTO sheet (id) VALUES (?)", id);
215	            seedSheet(id, sheet.get("people"), sheet.get("patrons"), "sheets.");
216	        }
217	        // Keep generated ids clear of the seeded ones.
218	        Long next = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) + 1 FROM person", Long.class);
219	        jdbc.execute("ALTER TABLE person ALTER COLUMN id RESTART WITH " + next);
220	    }
221	
222	    /** Inserts one sheet's people and then their patrons; a null sheet id is the unnamed sheet. */
223	    private void seedSheet(String sheetId, Object peopleRows, Object patronRows, String prefix) {
224	        for (Map<String, Object> row : rows(peopleRows, prefix + "people")) {
225	            for (String field : row.keySet()) {
226	                if (!PERSON_FIELDS.contains(field)) {
227	                    throw badRequest("cannot store " + prefix + "people." + field);
228	                }
229	            }
230	            if (!(row.get("name") instanceof String name)) {
231	                throw badRequest(prefix + "people.name is required");
232	            }
233	            Object id = row.get("id");
234	            Integer alpha = integer(row.get("alpha"), prefix + "people.alpha");
235	            Integer beta = integer(row.get("beta"), prefix + "people.beta");
236	            Integer gamma = integer(row.get("gamma"), prefix + "people.gamma");
237	            if (id == null) {
238	                jdbc.update("INSERT INTO person (sheet_id, name, alpha, beta, gamma) VALUES (?, ?, ?, ?, ?)",
239	                        sheetId, name, alpha, beta, gamma);
240	            } else {
241	                jdbc.update("INSERT INTO person (id, sheet_id, name, alpha, beta, gamma) VALUES (?, ?, ?, ?, ?, ?)",
242	                        integer(id, prefix + "people.id"), sheetId, name, alpha, beta, gamma);
243	            }
244	        }
245	        // Patrons link people by id, so add them once every person exists.
246	        for (Map<String, Object> row : rows(patronRows, prefix + "patrons")) {
247	            for (String field : row.keySet()) {
248	                if (!PATRON_FIELDS.contains(field)) {
249	                    throw badRequest("cannot store " + prefix + "patrons." + field);
250	                }
251	            }
252	            Integer personId = integer(row.get("personId"), prefix + "patrons.personId");
253	            Integer patronId = integer(row.get("patronId"), prefix + "patrons.patronId");
254	            if (personId == null || patronId == null) {
255	                throw badRequest(prefix + "patrons rows need personId and patronId");
256	            }
257	            jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)", personId, patronId);
258	        }
259	    }
260	
261	    /**
262	     * Read back what is stored, in the same shape and with the same field names the fixtures use,
263	     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4). The
264	     * unnamed sheet's people are at the top level; each named sheet nests its own.
265	     */
266	    @GetMapping("/fixture")
267	    public Map<String, Object> fixture() {
268	        Map<String, Object> out = new LinkedHashMap<>(sheetContents(null));
269	        List<Map<String, Object>> sheets = new ArrayList<>();
270	        for (String id : jdbc.queryForList("SELECT id FROM sheet ORDER BY id", String.class)) {
271	            Map<String, Object> sheet = new LinkedHashMap<>();
272	            sheet.put("id", id);
273	            sheet.putAll(sheetContents(id));
274	            sheets.add(sheet);
275	        }
276	        out.put("sheets", sheets);
277	        return out;
278	    }
279	
280	    private Map<String, Object> sheetContents(String sheetId) {
281	        String where = sheetId == null ? "p.sheet_id IS NULL" : "p.sheet_id = ?";
282	        Object[] args = sheetId == null ? new Object[0] : new Object[] {sheetId};
283	        Map<String, Object> out = new LinkedHashMap<>();
284	        out.put("people", jdbc.queryForList("SELECT id AS \"id\", name AS \"name\", alpha AS \"alpha\", "
285	                + "beta AS \"beta\", gamma AS \"gamma\" FROM person p WHERE " + where + " ORDER BY id", args));
286	        out.put("patrons", jdbc.queryForList("SELECT pp.person_id AS \"personId\", pp.patron_id AS \"patronId\" "
287	                + "FROM person_patron pp JOIN person p ON p.id = pp.person_id WHERE " + where
288	                + " ORDER BY pp.person_id, pp.patron_id", args));
289	        return out;
290	    }
291	
292	    @SuppressWarnings("unchecked")
293	    private static List<Map<String, Object>> rows(Object value, String key) {
294	        if (value == null) {
295	            return List.of();
296	        }
297	        if (!(value instanceof List<?> list) || !list.stream().allMatch(r -> r instanceof Map)) {
298	            throw badRequest(key + " must be a list of rows");
299	        }
300	        return (List<Map<String, Object>>) list;
301	    }
302	
303	    private static Integer integer(Object value, String field) {
304	        if (value == null) {
305	            return null;
306	        }
307	        if (value instanceof Number n && n.doubleValue() == Math.rint(n.doubleValue())) {
308	            return n.intValue();
309	        }
310	        if (value instanceof String s && s.matches("-?\\d+")) {
311	            return Integer.valueOf(s);
312	        }
313	        throw badRequest(field + " must be a whole number, got " + value);
314	    }
315	
316	    private static ResponseStatusException badRequest(String message) {
317	        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
318	    }
319	}
